#define STACKSIZE 64hSignal sigstack[STACKSIZE];int stkptr;hSignal popsig() {	if (stkptr == 0) {		dprintf("*** Attempt to pop empty stack! ***\r");		return NULL;	} else {		return sigstack[--stkptr];	}}pushsig(hSignal sig) {	if (stkptr >= STACKSIZE) {		dprintf("*** Attempt to push full stack! ***\r");	} else {		sigstack[++stkptr] = sig;	}}pushcon(int id) {	hSignal sig;	sig = NewSignal(sigScalar, 1, 1L);	(**sig).dc = constval[id];	pushsig(sig);}hSignal NewSignal(int type, int temp, long len) {	hSignal sig;	float *ac, *acz;		sig = (hSignal)NewHandle(sizeof(oSignal));	(**sig).type = type;	(**sig).temp = temp;	if (type == sigSample) {		(**sig).ac = (float**)NewHandle(len * sizeof(float));		(**sig).length = len;	} else if (type == sigTable || type == sigEnvelope) {		(**sig).ac = (float**)NewHandle(tablesize * sizeof(float));		(**sig).length = len = 1024;	} else {		(**sig).ac = NULL;		(**sig).length = len = 0L;	}	(**sig).dc = 0.0;	if (len) {		HLock((**sig).ac);		ac = *(**sig).ac;		for (acz = ac + len; ac<acz; ) *ac++ = 0.0;		HUnlock((**sig).ac);	}	return sig;}KillTempSignal(hSignal sig) {	if ((**sig).temp) KillSignal(sig);}KillSignal(hSignal sig) {	if ((**sig).ac) {		DisposHandle((**sig).ac);	}	DisposHandle(sig);}assign(int id) {	hSignal in;	in = popsig();	if (vars[id].signal) KillSignal(vars[id].signal);	vars[id].signal = in;	(**in).temp = 0;}pushvar(int id) {	pushsig(vars[id].signal);}